mapper.select:
SELECT id, word, category, action, enabled, create_by, create_time, update_by, update_time
FROM content_sensitive_word

    AND word LIKE CONCAT('%', #{word}, '%')
    AND category = #{category}
    AND enabled = #{enabled}

ORDER BY id DESC

SELECT COUNT(*) FROM content_sensitive_hit
WHERE source = 'RESCAN' AND content_type = #{contentType} AND content_id = #{contentId}
  AND scan_version = #{scanVersion} AND action = #{action}

choose.otherwise:
SELECT id, CONCAT_WS('\n', name, description, keywords) AS text FROM club
WHERE id > #{afterId} AND status = 1 AND del_flag = 0
ORDER BY id LIMIT #{limit}
